// Calculate first and last day of previous month
const today = new Date();
const firstDayPrevMonth = new Date(today.getFullYear(), today.getMonth() - 1, 1);
const lastDayPrevMonth = new Date(today.getFullYear(), today.getMonth(), 0);

const formatDate = (date) => {
  return date.toISOString().split('T')[0];
};

// Generate list of expected dates
const expectedDates = [];
for (let d = new Date(firstDayPrevMonth); d <= lastDayPrevMonth; d.setDate(d.getDate() + 1)) {
  expectedDates.push(formatDate(new Date(d)));
}

return [{
  json: {
    startDate: formatDate(firstDayPrevMonth),
    endDate: formatDate(lastDayPrevMonth),
    monthName: firstDayPrevMonth.toLocaleString('default', { month: 'long', year: 'numeric' }),
    expectedDates: expectedDates,
    calculatedAt: new Date().toISOString()
  }
}];

// Filter S3 files for the specific month range
const monthInfo = $('Calculate Previous Month Range').first().json;
const s3Files = $input.all();
const startDate = monthInfo.startDate;
const endDate = monthInfo.endDate;

// Filter files that match date range
const relevantFiles = [];
for (const file of s3Files) {
  const key = file.json.Key;
  // Extract date from filename: processed/YYYY-MM-DD.json
  const dateMatch = key.match(/(\d{4}-\d{2}-\d{2})\.json$/);

  if (dateMatch) {
    const fileDate = dateMatch[1];
    if (fileDate >= startDate && fileDate <= endDate) {
      relevantFiles.push({
        key: key,
        date: fileDate,
        size: file.json.Size
      });
    }
  }
}

return [{
  json: {
    ...monthInfo,
    filesFound: relevantFiles.length,
    filesExpected: monthInfo.expectedDates.length,
    files: relevantFiles
  }
}];

// This node will need to download each file from S3 and aggregate
// For now, we'll prepare the structure and list of files to download

const item = $input.first().json;
const files = item.files;

// Create download requests for each file
const downloadRequests = files.map(file => ({
  json: {
    bucketName: 'lendly-fuel-transactions',
    fileName: file.key,
    date: file.date
  }
}));

return downloadRequests;

// Aggregate all daily files
const dailyRecords = $input.all();
const monthInfo = $('Fetch Daily Files from S3').first().json;

let totalAmount = 0;
let totalTransactions = 0;
let filesProcessed = 0;
let sequenceIssues = [];
let dailyBreakdown = [];

for (const record of dailyRecords) {
  try {
    // Parse the JSON data from S3 file
    const buffer = Buffer.from(record.binary.data.data, 'base64');
    const fileContent = buffer.toString('utf-8');
    const data = JSON.parse(fileContent);

    totalAmount += parseFloat(data.totalAmount || 0);
    totalTransactions += parseInt(data.transactionCount || 0);
    filesProcessed++;

    dailyBreakdown.push({
      date: data.fileDate,
      amount: data.totalAmount,
      transactions: data.transactionCount
    });

    if (!data.isSequential && data.sequenceWarning) {
      sequenceIssues.push({
        date: data.fileDate,
        warning: data.sequenceWarning
      });
    }
  } catch (error) {
    console.error('Error processing file:', error.message);
  }
}

return [{
  json: {
    monthName: monthInfo.monthName,
    startDate: monthInfo.startDate,
    endDate: monthInfo.endDate,
    totalAmount: parseFloat(totalAmount.toFixed(2)),
    totalTransactions: totalTransactions,
    filesProcessed: filesProcessed,
    filesExpected: monthInfo.filesExpected,
    filesMissing: monthInfo.filesExpected - filesProcessed,
    hasSequenceIssues: sequenceIssues.length > 0,
    sequenceIssues: sequenceIssues,
    dailyBreakdown: dailyBreakdown,
    calculatedAt: new Date().toISOString()
  }
}];

// Extract invoice amount from API response
const invoiceData = $input.first().json;

// Adjust these fields based on actual API response structure
const invoiceAmount = parseFloat(invoiceData.total_amount || invoiceData.amount || 0);
const invoiceNumber = invoiceData.invoice_number || invoiceData.id || 'N/A';
const invoiceDate = invoiceData.invoice_date || invoiceData.date || 'N/A';

return {
  json: {
    invoiceNumber: invoiceNumber,
    invoiceDate: invoiceDate,
    invoiceAmount: parseFloat(invoiceAmount.toFixed(2)),
    rawInvoiceData: invoiceData
  }
};

// Compare daily totals with invoice amount
const data = $input.first().json;

// Extract both merged data points
const dailyTotal = data.totalAmount;
const invoiceAmount = data.invoiceAmount;
const difference = dailyTotal - invoiceAmount;
const percentageDiff = invoiceAmount !== 0 
  ? ((difference / invoiceAmount) * 100).toFixed(2) 
  : 0;

const isReconciled = Math.abs(difference) < 0.01; // Within 1 cent tolerance

// Generate detailed report
const report = {
  reconciliationStatus: isReconciled ? 'MATCHED' : 'DISCREPANCY',
  monthName: data.monthName,
  periodStart: data.periodStart,
  periodEnd: data.periodEnd,

  dailyTotals: {
    amount: dailyTotal,
    filesProcessed: data.filesProcessed,
    filesExpected: data.filesExpected,
    filesMissing: data.filesMissing,
    totalTransactions: data.totalTransactions,
    sequenceIssues: data.sequenceIssues
  },

  invoice: {
    number: data.invoiceNumber,
    date: data.invoiceDate,
    amount: invoiceAmount
  },

  comparison: {
    difference: parseFloat(difference.toFixed(2)),
    percentageDiff: parseFloat(percentageDiff),
    isReconciled: isReconciled
  },

  dailyBreakdown: data.dailyBreakdown,

  reportGeneratedAt: new Date().toISOString()
};

return {
  json: report
};

